//! Native transport adapter for the MutationEngine generation owner. The
//! upstream stateless branch resolves one explicit agent/provider/model before
//! its versioned ACK and never constructs Agent/tools/memory. The WS adapter
//! must verify that ACK before sending the prompt; an older executable is not
//! compatible merely because its plugin contract has been rebuilt.
use crate::{
    generation_jobs_dispatch::GenerationBackend,
    zeroclow_router_generation_native::{NativeGenerationAdmission, NativeGenerationTask},
    zeroclow_router_runtime::ZeroClawRouterRuntimeClient,
};
use anyhow::Result;
use op_plugins::state_plugins::tched_router::generation::StartGenerationInput;
use std::sync::Arc;

impl GenerationBackend for ZeroClawRouterRuntimeClient {
    fn spawn(
        &self,
        input: StartGenerationInput,
        native_session: String,
        gate: Arc<dyn NativeGenerationAdmission>,
    ) -> Result<NativeGenerationTask> {
        self.spawn_stateless_generation(input, native_session, gate)
    }
}

//! Capability-preserving facade dispatch into canonical zeroclow_router methods.
//!
//! This module owns no provider, catalog, selection or generation state. The
//! facade call is admitted first, then the exact nested target method is
//! independently admitted and dispatched with the same verified identity.

use crate::{
    interceptor::load_capability_grants, method_contract_admission,
    mutation_engine::MutationEngine, project_dispatch,
};
use anyhow::{Context, Result};
use op_plugins::state_plugins::large_language_model_methods::{
    TargetPlan, complete_method, plan_method,
};

fn admit_target(plan: &TargetPlan, actor: &str) -> Result<()> {
    let declaration = method_contract_admission::admit_compiled_method(
        plan.plugin_id,
        plan.method,
        Some(&plan.required_capability),
    )?;
    method_contract_admission::validate_admitted_arguments(&declaration, &plan.args)?;
    anyhow::ensure!( … );
    Ok(())
}

/// Forward one already outer-admitted facade method through the canonical
/// target path. The recursive call intentionally performs target admission a
/// second time at the final effect boundary and records its own target audit.
