/// Refresh one paired config/selection observation while retaining the caller's
/// final admission and runtime guard through authoritative publication.
pub(crate) async fn observed_zeroclow_router_state(
    engine: &MutationEngine,
    pinned: &crate::sealed_schema_reader::ManifestPinnedSchemaDocument,
    sealed_identity: &str,
) -> Result<op_plugins::state_plugins::tched_router::TchedRouterState> {
    let (observed, represented) =
        crate::tched_config_engine::coherent_observation(pinned, sealed_identity).await?;
    engine
        .persist_zeroclow_router_observation(&represented, &pinned.schema_hash)
        .await
        .context("native zeroclow_router read completed but projection publication failed")?;
    Ok(observed)
}

/// Catalog authority for the separately admitted native binding reflection.
/// This helper reads no native configuration and grants no native authority.
pub(crate) async fn catalog_binding_target(
    engine: &MutationEngine,
    provider_id: &str,
    model_id: &str,
) -> Result<crate::tched_catalog_binding::BindingTarget> {
    binding_target_from(
        &Environment::from_env(),
        engine.model_registry_cozo().await?,
        provider_id,
        model_id,
    )
    .await
}

