/// final admission and runtime guard through authoritative publication.
pub(crate) async fn observed_zeroclow_router_state(
    engine: &MutationEngine,
    pinned: &crate::sealed_schema_reader::ManifestPinnedSchemaDocument,
    sealed_identity: &str,
) -> Result<op_plugins::state_plugins::chat_router::ChatRouterState> {
    let (observed, represented) =
        crate::zeroclow_config_engine::coherent_observation(pinned, sealed_identity).await?;
    engine
        .persist_zeroclow_router_observation(&represented, &pinned.schema_hash)
        .await
            .context("native zeroclow_router read completed but projection publication failed")?;
    Ok(observed)
}

